func(ctx context.Context) {
			detachedCtx := context.WithoutCancel(ctx)
			// The publishing of all partners can take some time, hence allow up to 5 minutes.
			timeoutCtx, cancel := context.WithTimeout(detachedCtx, 5*time.Minute)
			defer cancel()

			partners, err := a.rdmClient.GetAllPartnersData(timeoutCtx)
			if err != nil {
				a.logger.Error("Failed to get all partners data: ", err)
				return
			}

			err = a.eventWriter.PublishPartners(timeoutCtx, partners)
			if err != nil {
				a.logger.Error("Failed to publish partners: ", err)
			}
		}
